mapper.update:
UPDATE notify_channel
SET enabled    = #{value.enabled},
    config     = #{value.config},
    secret     = #{value.secret},
    updated_at = #{value.updatedAt}
WHERE channel = #{value.channel}

mapper.select:
SELECT id, event_type, event_id, rule_name, kind, channel, recipient, status, error, sent_at
FROM notify_record

    event_type = #{eventType}
    AND event_id = #{eventId}

ORDER BY sent_at DESC, id DESC
LIMIT #{limit}
